BEGIN;SET search_path=labassist_student,public;
\ir ../../remaining-data/tests/helpers.sql
CREATE TEMP TABLE test_day AS SELECT max(day) AS day FROM workshop_days WHERE term_id=(SELECT term FROM f) AND is_working;
SELECT pg_temp.ok('absence threshold has no guessed default',NOT EXISTS(SELECT 1 FROM workshop_absence_policies WHERE limit_percent IS NOT NULL));
SELECT pg_temp.ok('historical tools were returned by all fifteen teams',(SELECT count(*)=15 FROM workshop_handover_summary h JOIN projects p ON p.id=h.project_id WHERE p.seed_key LIKE 'PAST_TEAM%' AND h.outstanding=0));
SELECT pg_temp.ok('every current team has exactly one initial table',(SELECT count(*)=23 FROM workshop_table_assignments WHERE term_id=(SELECT term FROM f)));
SELECT pg_temp.ok('physical and term capacity are separate',(SELECT sum(team_capacity)=31 FROM workshop_tables) AND (SELECT team_capacity=25 FROM term_workshop_capacity WHERE term_id=(SELECT term FROM f)));
SELECT pg_temp.reject('working day requires both opening and closing times',$q$SELECT set_workshop_day(manager,term,(SELECT day FROM test_day),true,'08:00',NULL,'Missing closing time',0) FROM f$q$,'check constraint');
SELECT pg_temp.reject('student cannot mark attendance',$q$SELECT record_attendance(owner,term,(SELECT day FROM test_day),owner,0,'ABSENT') FROM f$q$,'manager required');
SELECT record_attendance(manager,term,(SELECT day FROM test_day),owner,0,'ABSENT') FROM f;
SELECT pg_temp.reject('stale attendance edit rejected',$q$SELECT record_attendance(manager,term,(SELECT day FROM test_day),owner,0,'PRESENT') FROM f$q$,'revision conflict');
SELECT pg_temp.reject('attendance accepts only present or absent',$q$SELECT record_attendance(manager,term,(SELECT day FROM test_day),owner,1,'EXCUSED') FROM f$q$,'check constraint');
SELECT pg_temp.reject('attendance older than a week is read only',$q$SELECT record_attendance(manager,term,current_date-8,owner,-1,'ABSENT') FROM f$q$,'edit window closed');
SELECT pg_temp.ok('unset policy creates no absence alert',(SELECT check_repeated_absence(manager,owner,term) IS NULL FROM f));
SELECT set_absence_policy(manager,term,0,1) FROM f;
INSERT INTO ids SELECT 'alert',check_repeated_absence(manager,owner,term) FROM f;
SELECT pg_temp.ok('repeated absence produces one alert only',(SELECT check_repeated_absence(manager,owner,term)=(SELECT id FROM ids WHERE key='alert') FROM f) AND (SELECT count(*)=1 FROM notification_events WHERE workshop_record_id=(SELECT id FROM ids WHERE key='alert')));
SELECT pg_temp.ok('alert reaches student and their supervisor',(SELECT count(*)>=2 FROM workshop_record_recipients WHERE record_id=(SELECT id FROM ids WHERE key='alert')));
SELECT set_workshop_day(manager,term,(SELECT day FROM test_day),false,NULL,NULL,'Road closure fixture',0) FROM f;
SELECT pg_temp.ok('closures are excluded from absence calculations',(SELECT absences=0 FROM workshop_absence_summary WHERE student_id=(SELECT owner FROM f) AND term_id=(SELECT term FROM f)));
SELECT pg_temp.reject('attendance cannot be changed on a closed day',$q$SELECT record_attendance(manager,term,(SELECT day FROM test_day),owner,1,'PRESENT') FROM f$q$,'working day');
INSERT INTO ids SELECT 'notice',create_workshop_record(manager,term,project,'NOTICE','Schedule reminder',true,true) FROM f;
SELECT pg_temp.reject('workshop extension preserves notification key validation',$q$INSERT INTO notification_events(event_key,kind,actor_id,workshop_record_id) SELECT '','WORKSHOP_UPDATE',manager,(SELECT id FROM ids WHERE key='notice') FROM f$q$,'check constraint');
SELECT pg_temp.reject('workshop extension preserves notification payload validation',$q$INSERT INTO notification_events(event_key,kind,actor_id,workshop_record_id,data) SELECT 'invalid-payload','WORKSHOP_UPDATE',manager,(SELECT id FROM ids WHERE key='notice'),'[]'::jsonb FROM f$q$,'check constraint');
SELECT edit_workshop_record(manager,(SELECT id FROM ids WHERE key='notice'),0,'Updated schedule reminder') FROM f;
SELECT pg_temp.reject('foreign team cannot read targeted notice',$q$SELECT read_workshop_record(outsider,(SELECT id FROM ids WHERE key='notice')) FROM f$q$,'access denied');
SELECT pg_temp.ok('linked supervisor can read targeted notice',(SELECT read_workshop_record(supervisor,(SELECT id FROM ids WHERE key='notice'))->>'body'='Updated schedule reminder' FROM f));
SELECT pg_temp.reject('notice is immutable after recipient viewing',$q$SELECT edit_workshop_record(manager,(SELECT id FROM ids WHERE key='notice'),1,'Late edit') FROM f$q$,'seen');
INSERT INTO ids SELECT 'observation',create_workshop_record(manager,term,project,'OBSERVATION','Review the work area.',false,true) FROM f;
SELECT pg_temp.ok('observation is routed to supervisors, not the whole student roster',EXISTS(SELECT 1 FROM workshop_record_recipients WHERE record_id=(SELECT id FROM ids WHERE key='observation') AND account_id=(SELECT supervisor FROM f)) AND NOT EXISTS(SELECT 1 FROM workshop_record_recipients WHERE record_id=(SELECT id FROM ids WHERE key='observation') AND account_id=(SELECT owner FROM f)));
SELECT assign_workshop_table(owner,project,'C1',0) FROM f;
SELECT pg_temp.ok('student table changes require manager confirmation',(SELECT verified_by IS NULL AND table_id='C1' FROM workshop_table_assignments WHERE project_id=(SELECT project FROM f)));
SELECT pg_temp.reject('another team cannot move this team',$q$SELECT assign_workshop_table(outsider,project,'C2',1) FROM f$q$,'own teammate');
SELECT pg_temp.reject('student cannot verify the assignment',$q$SELECT verify_workshop_table(owner,project,1) FROM f$q$,'manager required');
SELECT verify_workshop_table(manager,project,1) FROM f;
SELECT pg_temp.reject('occupied rectangular table rejects another team',$q$SELECT assign_workshop_table(owner,project,'R2',2) FROM f$q$,'capacity exceeded');
SELECT pg_temp.ok('table history preserves the prior allocation',(SELECT count(*)=3 FROM workshop_table_history WHERE project_id=(SELECT project FROM f)));
INSERT INTO ids SELECT 'handover',id FROM workshop_handovers WHERE project_id=(SELECT project FROM f);
INSERT INTO ids SELECT 'tool',id FROM workshop_handover_items WHERE handover_id=(SELECT id FROM ids WHERE key='handover') ORDER BY id LIMIT 1;
CREATE TEMP TABLE return_payload AS SELECT jsonb_build_array(jsonb_build_object('id',(SELECT id FROM ids WHERE key='tool'),'good',1,'damaged',0,'missing',0)) AS data;
SELECT update_tool_return(manager,(SELECT id FROM ids WHERE key='handover'),0,'66000000-0000-4000-8000-000000000001',(SELECT data FROM return_payload)) FROM f;
SELECT pg_temp.ok('partial tool returns keep outstanding quantities',(SELECT outstanding=2 FROM workshop_handover_summary WHERE id=(SELECT id FROM ids WHERE key='handover')));
SELECT pg_temp.ok('return retry has one persisted update',(SELECT update_tool_return(manager,(SELECT id FROM ids WHERE key='handover'),0,'66000000-0000-4000-8000-000000000001',(SELECT data FROM return_payload))=1 FROM f) AND (SELECT count(*)=1 FROM workshop_return_updates WHERE handover_id=(SELECT id FROM ids WHERE key='handover')));
SELECT pg_temp.reject('tools cannot be returned above issued quantity',$q$SELECT update_tool_return(manager,(SELECT id FROM ids WHERE key='handover'),1,gen_random_uuid(),jsonb_build_array(jsonb_build_object('id',(SELECT id FROM ids WHERE key='tool'),'good',2,'damaged',0,'missing',0))) FROM f$q$,'check constraint');
SELECT pg_temp.reject('student cannot edit team tool returns',$q$SELECT update_tool_return(owner,(SELECT id FROM ids WHERE key='handover'),1,gen_random_uuid(),(SELECT data FROM return_payload)) FROM f$q$,'manager required');
SELECT pg_temp.reject('unrelated student cannot view team handovers',$q$SELECT read_team_handovers(outsider,project) FROM f$q$,'access denied');
SET CONSTRAINTS ALL IMMEDIATE;ROLLBACK;
